          <button
            onClick={() => shiftDay(-1)}
            aria-label="Previous day"
            className="h-11 w-8 lg:h-8 lg:w-7 shrink-0 grid place-items-center rounded-sm text-mute hover:text-ink hover:bg-card/70 transition text-base leading-none"
          >‹</button>
